"""RDF triples as a graph: lookups, multi-hop traversal, and RDFS type inference."""
from collections import defaultdict

triples = [
    ("Rahul", "ordered", "Margherita"), ("Margherita", "hasPrice", "250"), ("Margherita", "isOfType", "Veg"),
    ("Priya", "ordered", "Pepperoni"), ("Pepperoni", "hasPrice", "320"), ("Pepperoni", "isOfType", "NonVeg"),
    ("Rahul", "rdf:type", "Customer"), ("Priya", "rdf:type", "Customer"),
    ("Margherita", "rdf:type", "Pizza"), ("Pepperoni", "rdf:type", "Pizza"),
    ("Pizza", "rdfs:subClassOf", "Food"), ("Customer", "rdfs:subClassOf", "Person"),
    ("Food", "rdfs:subClassOf", "Product"),
]
out = defaultdict(list)
for s, p, o in triples: out[s].append((p, o))

def query(s=None, p=None, o=None):
    return [t for t in triples if (s is None or t[0] == s) and (p is None or t[1] == p) and (o is None or t[2] == o)]

print("1-hop: what did Rahul order?", [o for _, _, o in query("Rahul", "ordered")])
print("2-hop: price of what Rahul ordered:", [o2 for _, _, o in query("Rahul", "ordered") for _, _, o2 in query(o, "hasPrice")])
print("who ordered a veg pizza?", [s for s, _, o in query(p="ordered") if query(o, "isOfType", "Veg")])

# RDFS inference: types propagate up rdfs:subClassOf (transitively)
def superclasses(c):
    res, frontier = set(), [c]
    while frontier:
        x = frontier.pop()
        for _, _, y in query(x, "rdfs:subClassOf"):
            if y not in res: res.add(y); frontier.append(y)
    return res
inferred = {(s, "rdf:type", sup) for s, _, c in query(p="rdf:type") for sup in superclasses(c)}
for t in sorted(inferred): print("inferred:", t)

# Same meaning, different predicates: why standard vocabularies matter
raw = [("Rahul", "ordered", "Margherita"), ("Asha", "bought", "Margherita"), ("Ben", "placedOrderFor", "Margherita")]
print("naive query for 'ordered' finds", len([t for t in raw if t[1] == "ordered"]), "of", len(raw), "orders")
SAME = {"ordered": "schema:orderedItem", "bought": "schema:orderedItem", "placedOrderFor": "schema:orderedItem"}
print("after mapping to one vocabulary:", len([t for t in raw if SAME[t[1]] == "schema:orderedItem"]), "of", len(raw))

"""OWL-style reasoning (transitive, symmetric, inverse, disjoint) and community detection on a small KG."""
import networkx as nx

facts = {("egg", "isInsideOf", "sandwich"), ("sandwich", "isInsideOf", "lunchbox"),
         ("cheese", "pairsWith", "tomato"), ("sandwich", "contains", "cheese"),
         ("Ravi", "hasWife", "Meera"), ("Ravi", "hasHusband", "Meera")}
TRANSITIVE, SYMMETRIC = {"isInsideOf"}, {"pairsWith"}
INVERSE = {"contains": "isIngredientOf"}
DISJOINT = [("hasWife", "hasHusband")]

def closure(F):
    F = set(F)
    while True:
        new = set()
        for (a, p, b) in F:
            if p in SYMMETRIC: new.add((b, p, a))
            if p in INVERSE: new.add((b, INVERSE[p], a))
            if p in TRANSITIVE:
                new |= {(a, p, d) for (c, q, d) in F if q == p and c == b}
        if new <= F: return F
        F |= new

C = closure(facts)
for t in sorted(C - facts): print("inferred:", t)
for p1, p2 in DISJOINT:
    for (a, p, b) in C:
        if p == p1 and (a, p2, b) in C: print(f"inconsistency: {a} {p1} {b} and {a} {p2} {b} (disjoint properties)")

# A small knowledge graph with two hidden communities joined by a bridge
G = nx.Graph()
G.add_edges_from([("Rahul", "AI"), ("Rahul", "College"), ("Asha", "AI"), ("Asha", "College"), ("AI", "CS"),
                  ("College", "Jaipur"), ("Jaipur", "Rajasthan"), ("Rajasthan", "India"),
                  ("Margherita", "Pizza"), ("Pepperoni", "Pizza"), ("Pizza", "Food"), ("Priya", "Pepperoni"),
                  ("Priya", "Margherita"), ("Rahul", "Margherita")])
print("2-hop neighbourhood of Rahul:", sorted(nx.single_source_shortest_path_length(G, "Rahul", cutoff=2)))
comms = nx.community.louvain_communities(G, seed=1)
for i, c in enumerate(sorted(comms, key=len, reverse=True)): print(f"community {i}: {sorted(c)}")
print("path Asha -> India:", nx.shortest_path(G, "Asha", "India"))
